import {products,subtests,scoreAnswer,references,missingFor,displayLabels} from './data.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], key='taruna-dashboard-flow-v3';
const initial=fresh=>({fresh,balance:fresh?0:107000,holdings:fresh?[]:['kedinasan','polri'],credits:fresh?{}:{campur:4},cart:fresh?[]:['simbol'],selectedCart:fresh?null:'simbol',orders:[],normal:{},kec:{},history:fresh?[]:[{id:'contoh-polri',kind:'tryout',product:'polri',score:76,sample:true,date:'26 Okt 2026'},{id:'contoh-kedinasan',kind:'tryout',product:'kedinasan',score:84,sample:true,date:'30 Okt 2026'}],profile:{name:fresh?'Astuti Simorangkir':'Naila Ramadhani',email:fresh?'astuti@example.test':'naila@example.test'},palette:'rose',theme:'light'});
let model;try{model=JSON.parse(sessionStorage.getItem(key))||initial(false);}catch{model=initial(false);}
let hub='tryout',filter='all',search='',method='saldo',amount=50000,currentPath='',toastTimer;
const save=()=>sessionStorage.setItem(key,JSON.stringify(model));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#${id}"/></svg>`;
const rp=n=>'Rp'+Number(n).toLocaleString('id-ID');
const pFor=id=>products.find(p=>p.id===id)||products[0];
const has=p=>p.kind==='tryout'?model.holdings.includes(p.id):Number(model.credits[p.id]||0)>0;
const action=(label,route,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="#${route}" data-route="${route}">${label}${icon('arrow')}</a>`;
const btn=(label,a,secondary=false,disabled=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${a}" ${disabled?'disabled':''}>${label}${icon('arrow')}</button>`;
const textLink=(label,route)=>`<a class="text-button" data-route="${route}" href="#${route}">${label}${icon('arrow')}</a>`;
const crumb=(label='Tryout',route='/latihan')=>`<div class="breadcrumb"><a data-route="/dashboard" href="#/dashboard">Dashboard</a>${icon('chevron')}<a data-route="${route}" href="#${route}">${label}</a></div>`;
const title=(h,p,extra='')=>`<div class="page-heading"><div><h1>${h}</h1><p>${p}</p></div>${extra}</div>`;
const empty=(h,p,route='/katalog',label='Jelajahi katalog')=>`<div class="panel empty-screen">${icon('book')}<h2>${h}</h2><p>${p}</p>${action(label,route)}</div>`;
const message=(text,green=false)=>`<div class="note-box ${green?'green':''}">${text}</div>`;
const routeFor=p=>`/${p.kind==='tryout'?'tryout':'kecermatan'}/${p.id}`;
const historyFor=id=>model.history.filter(r=>r.product===id);
const dateNow=()=>new Date().toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
const answered=a=>Array.isArray(a)?a.length>0:a!==undefined&&a!==null&&String(a).trim()!=='';
const seconds=end=>Math.max(0,Math.ceil((end-Date.now())/1000));
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const selectedProduct=()=>pFor(model.selectedCart||model.cart[0]);
function go(path,push=true){if(!path.startsWith('/'))path='/'+path;closeWallet();closeProfile();if(push)location.hash=path;else history.replaceState(null,'','#'+path);render();window.scrollTo(0,0);}
function notify(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function closeProfile(){$('#profile-menu').hidden=true;$('#profile-trigger').setAttribute('aria-expanded','false');}
function closeWallet(){if($('#account-dialog').open)$('#account-dialog').close();}
function setTheme(){document.documentElement.dataset.palette=model.palette;document.documentElement.dataset.theme=model.theme;}
function dashboard(){const normals=products.filter(p=>p.kind==='tryout'&&has(p)),ke=products.filter(p=>p.kind==='kecermatan'&&has(p)),normal=normals[0],kec=ke[0],nHistory=model.history.filter(r=>r.kind==='tryout'),average=nHistory.length?(nHistory.reduce((s,r)=>s+r.score,0)/nHistory.length).toLocaleString('id-ID',{maximumFractionDigits:1}):'—';return `${title(`Halo, ${esc(model.profile.name.split(' ')[0])}.`,'Pilih latihanmu. Lanjutkan langkah berikutnya.',action('Lihat katalog','/katalog',true))}${model.fresh?message('Email belum diverifikasi. Kamu tetap bisa menggunakan akun. '+textLink('Verifikasi email','/akun/verifikasi')):''}
<div class="practice-entry-grid"><section class="entry-card"><span class="card-kicker">${icon('book')}Tryout</span><h2>${normal?normal.title:'Persiapan yang lebih terarah.'}</h2><p>${normal?'TWK, TIU, dan TKP. Jawab soal dengan tenang, satu subtes pada satu waktu.':'Temukan tryout sesuai tujuan, lalu pelajari hasil dan pembahasannya.'}</p><div class="practice-bottom"><span class="practice-meta">${icon('clock')}${normal?'3 subtes · 90 menit':'TNI · POLRI · Kedinasan'}</span>${action(normal?'Buka tryout':'Pilih tryout',normal?routeFor(normal):'/katalog')}</div></section>
<section class="entry-card kec"><span class="card-kicker">${icon('spark')}Tes kecermatan</span><h2>${kec?kec.title:'Latih fokus dan ketelitian.'}</h2><p>Kenali referensi, temukan item yang hilang, lalu jaga ritme jawabanmu.</p><div class="practice-bottom"><span class="practice-meta">${kec?`<strong class="remaining">${model.credits[kec.id]}</strong>kesempatan tersisa`:'Tes simbol, angka, dan campuran'}</span>${action(kec?'Buka tes':'Pilih tes',kec?routeFor(kec):'/katalog?jenis=kecermatan')}</div></section></div>
<div class="metric-strip">${[[normals.length,'Tryout dimiliki','book'],[ke.reduce((n,p)=>n+(model.credits[p.id]||0),0),'Kuota tes kecermatan','spark'],[average,'Rata-rata skor tryout','chart']].map(([n,label,ic])=>`<div class="metric"><span class="metric-icon">${icon(ic)}</span><div><strong>${n}</strong><small>${label}</small></div></div>`).join('')}</div>
<div class="lower-grid"><section><div class="section-heading"><h2>Latihan saya</h2>${textLink('Lihat semua','/latihan')}</div><div class="tryout-list">${[...normals,...ke].length?[...normals,...ke].map(p=>`<a href="#${routeFor(p)}" data-route="${routeFor(p)}" class="tryout-row"><span class="product-symbol ${p.tone}">${icon(p.icon)}</span><span class="tryout-title"><strong>${p.title}</strong><small>${p.kind==='tryout'?p.access:`${model.credits[p.id]} kesempatan tersedia`}</small></span>${icon('arrow')}</a>`).join(''):`<p class="empty-content">Belum ada latihan yang dimiliki. ${textLink('Jelajahi katalog','/katalog')}</p>`}</div></section><section><div class="section-heading"><h2>Hasil terakhir</h2><span class="quiet-chip">Semua latihan</span></div>${model.history.length?model.history.slice(-3).reverse().map(r=>`<a href="#/hasil/${r.kind}/${r.id}" data-route="/hasil/${r.kind}/${r.id}" class="result-row"><span class="result-score">${r.score}<small>/ 100</small></span><div><strong>${pFor(r.product).title}</strong><small>${r.kind==='tryout'?'Tryout':'Kecermatan'} · ${r.date}</small></div>${icon('arrow')}</a>`).join(''):`<p class="empty-content">Selesaikan latihan pertamamu. Hasil dan pembahasan akan tampil di sini.</p>`}<p class="insight">${icon('spark')}<span>Tryout dan kecermatan punya hasil terpisah, agar setiap latihan lebih mudah dievaluasi.</span></p></section></div>`;}
function productCard(p,catalog=false){const owned=has(p),pending=p.kind==='tryout'?model.normal[p.id]?.phase==='running':['kolom','pause'].includes(model.kec[p.id]?.phase);return `<article class="product-card"><span class="product-symbol ${p.tone}">${icon(p.icon)}</span><span class="card-kicker">${p.kind==='tryout'?p.program:'Tes kecermatan'}</span><h3>${p.title}</h3><p>${p.description}</p>${!catalog||owned?`<span class="access-label">${icon('check')}${p.kind==='tryout'?p.access:`${model.credits[p.id]||0} kesempatan tersedia`}</span>`:''}<div class="card-actions"><span class="${catalog?'price':'quiet-chip'}">${catalog?rp(p.price):pending?'Sesi sedang berjalan':p.kind==='tryout'?`${historyFor(p.id).length} percobaan selesai`:'10 kolom · 50 soal/kolom'}</span>${textLink(pending?'Lanjutkan':catalog?'Lihat detail':'Buka latihan',routeFor(p))}</div></article>`;}
function library(catalog=false){let list=products.filter(p=>(catalog||has(p))&&(filter==='all'||p.kind===filter)&&p.title.toLowerCase().includes(search.toLowerCase()));if(!catalog)list=list.filter(p=>p.kind===hub);return `${title(catalog?'Pilih langkah berikutnya.':'Tryout & kecermatan',catalog?'Beli akses tryout atau tambahan kuota tes kecermatan.':'Dua jenis latihan. Pilih ruang yang ingin kamu buka.',catalog?textLink(`Keranjang (${model.cart.length})`,'/keranjang'):action('Jelajahi katalog','/katalog',true))}${!catalog?`<div class="hub-tabs"><button class="hub-tab ${hub==='tryout'?'active':''}" data-hub="tryout">Tryout <small>${products.filter(p=>p.kind==='tryout'&&has(p)).length}</small></button><button class="hub-tab ${hub==='kecermatan'?'active':''}" data-hub="kecermatan">Tes kecermatan <small>${products.filter(p=>p.kind==='kecermatan'&&has(p)).length}</small></button></div>`:''}<div class="filters">${catalog?['all','tryout','kecermatan'].map(v=>`<button class="filter ${filter===v?'selected':''}" data-filter="${v}">${v==='all'?'Semua':v==='tryout'?'Tryout':'Tes kecermatan'}</button>`).join(''):''}<label class="search">${icon('search')}<input id="search" aria-label="Cari latihan" placeholder="Cari latihan…" value="${esc(search)}"></label></div>${list.length?`<div class="product-grid">${list.map(p=>productCard(p,catalog)).join('')}</div>`:empty('Belum ada latihan di sini.','Pilih latihan di katalog untuk mulai. Kamu tetap bisa melihat kedua jenis latihan.')}`;}
function detail(p){const owned=has(p),k=p.kind==='kecermatan',n=model.normal[p.id],kr=model.kec[p.id],active=k?kr&&['kolom','pause'].includes(kr.phase):n&&['running','between'].includes(n.phase);return `${crumb(k?'Tes kecermatan':'Tryout')}<div class="detail-grid"><div><section class="detail-hero ${k?'kec':''}"><span class="card-kicker">${icon(p.icon)}${k?'Tes kecermatan':p.program}</span><h1>${p.title}</h1><p>${p.description}</p><div class="facts">${(k?[[10,'Kolom'],[50,'Soal / kolom'],['60 detik','Durasi / kolom']]:[[3,'Subtes'],[100,'Soal'],['90 menit','Durasi total']]).map(([n,label])=>`<div class="fact"><strong>${n}</strong><small>${label}</small></div>`).join('')}</div></section>
<section class="panel"><h2>${k?'Cara mengerjakan':'Susunan subtes'}</h2>${k?`<ol class="feature-list"><li>Pelajari lima item referensi berlabel A–E.</li><li>Perhatikan empat item yang ditampilkan pada soal.</li><li>Pilih label item yang hilang. Jawaban langsung berpindah ke soal berikutnya.</li><li>Setiap kolom punya timer bersama. Soal tersisa dicatat kosong saat waktu habis.</li><li>Jeda singkat muncul sebelum kolom berikutnya.</li></ol><div class="instructions-sample"><span class="kec-label">Contoh referensi</span><div class="reference-grid">${['▲','●','◆','■','✦'].map((s,i)=>`<div class="reference-box"><small>${'ABCDE'[i]}</small><strong>${s}</strong></div>`).join('')}</div><span class="kec-label">Jika tampil ▲ ● ■ ✦, item yang hilang adalah C (◆).</span></div>`:subtests.map((s,i)=>`<div class="subtest-row"><span class="subtest-number">${i+1}</span><div><strong>${s.name}</strong><small>${s.short}</small></div><span>${[30,35,35][i]} soal · 30 menit</span></div>`).join('')}${message(k?'Kuota diperlukan untuk memulai, dan berkurang setelah tes selesai. Tes ini tidak memakai peringkat atau pengawasan fullscreen.':'Kamu bebas berpindah soal dalam subtes yang sedang berjalan. Setelah dikumpulkan atau waktu habis, subtes tersebut terkunci.')}</section>
<section class="panel"><h2>Riwayat percobaan</h2>${historyFor(p.id).length?historyFor(p.id).slice().reverse().map((r,i)=>`<a class="history-row" href="#/hasil/${r.kind}/${r.id}" data-route="/hasil/${r.kind}/${r.id}"><div>Percobaan ${historyFor(p.id).length-i}<small>${r.date}</small></div><strong>${r.score}</strong>${icon('arrow')}</a>`).join(''):'<p>Belum ada percobaan. Hasil pertama akan tersimpan di sini setelah latihan selesai.</p>'}</section></div>
<aside class="panel sticky-summary"><p class="summary-title">${owned?'Akses latihan':'Produk latihan'}</p><div class="summary-price">${owned?(k?`${model.credits[p.id]} kali`:'Sudah dimiliki'):rp(p.price)}</div><p class="summary-sub">${owned?(k?'Sisa kesempatan tes':p.access):p.access}</p>${owned?action(active?'Lanjutkan sesi':k?'Mulai tes':'Mulai tryout',active?(k?`/tes-kecermatan/${p.id}`:n.phase==='between'?`/ujian/${p.id}/transisi`:`/ujian/${p.id}`):`${routeFor(p)}/persiapan`):`<button class="button wide-button" data-add="${p.id}">Tambahkan ke keranjang${icon('arrow')}</button>`}${k&&owned?`<button class="button secondary wide-button" data-add="${p.id}">Beli tambahan kuota${icon('arrow')}</button>`:''}${textLink('Kembali ke latihan','/latihan')}${message('Prototype singkat tersedia: tryout 6 soal; kecermatan 20 detik per kolom. Data dan waktu hanya simulasi lokal.')}</aside></div>`;}
function prepare(p){const k=p.kind==='kecermatan';if(!has(p))return empty(k?'Kuota tes sudah habis.':'Akses latihan belum tersedia.','Buka detail untuk membeli akses atau tambahan kuota.',routeFor(p),'Lihat detail');return `${crumb(k?'Tes kecermatan':'Tryout')}<div class="preflight">${title(k?'Siapkan ritmemu.':'Siap memulai tryout?',p.title)}<div class="readiness"><section class="panel"><h2>${k?'Satu kolom, satu ritme.':'Satu subtes pada satu waktu.'}</h2><ul class="feature-list">${k?'<li>Referensi A–E tetap sama selama satu kolom.</li><li>Pilih label item yang hilang, atau lewati soal.</li><li>Jawaban tidak bisa diubah setelah dikirim.</li><li>Timer terus berjalan saat berpindah halaman.</li><li>Jeda 5 detik antar-kolom. Bisa lanjut lebih awal.</li>':'<li>Pilih atau isi jawaban, lalu navigasikan soal.</li><li>Kamu bisa mengubah jawaban sebelum mengumpulkan subtes.</li><li>Subtes yang dikumpulkan tidak dapat dibuka kembali.</li><li>Waktu berhenti di antara subtes sampai kamu mulai lagi.</li>'}</ul>${message(k?'Demo: 10 kolom, 50 soal per kolom, 20 detik per kolom. Tombol “Percepat waktu” hanya kontrol prototype.':'Demo: 3 subtes, masing-masing 2 soal dan 45 detik. Tidak membuka fullscreen perangkat.')}</section><section class="panel"><h2>Periksa sebelum mulai</h2><p>${k?`${model.credits[p.id]} kesempatan tersedia. Satu kesempatan digunakan setelah tes selesai.`:p.access}</p><form id="ready-form" data-id="${p.id}"><label class="check-line"><input type="checkbox" required>Saya sudah membaca petunjuk dan siap mengerjakan.</label><button class="button wide-button">${k?'Mulai tes kecermatan':'Mulai subtes pertama'}${icon('arrow')}</button></form>${textLink('Kembali ke detail',routeFor(p))}</section></div></div>`;}
function startNormal(id){let r=model.normal[id];if(!r||r.phase==='completed')r=model.normal[id]={id:'try-'+Date.now(),kind:'tryout',product:id,part:0,q:0,answers:{},submitted:[],phase:'ready',deadline:null};if(r.phase==='ready'||r.phase==='between'){r.phase='running';r.deadline=Date.now()+45000;}save();go('/ujian/'+id);}
function submitPart(id,expired=false){const r=model.normal[id];if(!r||r.phase!=='running')return;r.submitted.push(r.part);r.deadline=null;if(r.part<2){r.part++;r.q=0;r.phase='between';}else{r.phase='completed';let correct=0,wrong=0,blank=0;r.parts=subtests.map((s,si)=>{let c=0;s.questions.forEach((q,qi)=>{const a=r.answers[si+'-'+qi];if(!answered(a))blank++;else if(scoreAnswer(q,a)){correct++;c++;}else wrong++;});return Math.round(c/s.questions.length*100);});r.counts={correct,wrong,blank};r.score=Number((correct/6*100).toFixed(2));r.date=dateNow();model.history.push(JSON.parse(JSON.stringify(r)));}save();if(currentPath.startsWith('/ujian/'))go(r.phase==='completed'?'/hasil/tryout/'+r.id:'/ujian/'+id+'/transisi',false);if(expired)notify('Waktu subtes habis. Jawaban demo dikumpulkan.');}
function examHeader(p,r,k=false){return `<header class="exam-topbar"><img src="../assets/logo.png" alt="Taruna Eduka"><div class="exam-title"><strong>${p.title}</strong><small>${k?`Kolom ${r.col+1} / 10`:`${subtests[r.part]?.short||'Tryout'} · Subtes ${r.part+1} / 3`}</small></div><div class="exam-timer">${icon('clock')}<span data-clock>${time(seconds(k&&r.phase==='pause'?r.pauseUntil:r.deadline||Date.now()))}</span></div></header><div class="demo-runtime"><span>Prototype · jawaban, waktu, dan hasil hanya disimpan di sesi browser ini.</span><button data-action="expire-${k?'kec':'normal'}" data-id="${p.id}">Percepat waktu ${k?'kolom':'subtes'}</button></div>`;}
function normalExam(id,mode){const p=pFor(id),r=model.normal[id];if(!r)return prepare(p);if(r.phase==='completed')return resultPage('tryout',r.id);if(r.phase==='between')return `${examHeader(p,r)}<div class="exam-center"><section class="panel"><span class="answer-status correct">Subtes sebelumnya sudah dikumpulkan</span><h1>Lanjut ke ${subtests[r.part].short}.</h1><p>Ambil jeda sebentar. Timer ${subtests[r.part].name} mulai berjalan saat kamu menekan tombol di bawah.</p>${message('Subtes sebelumnya sudah terkunci. Jawaban di subtes berikutnya dimulai dari kosong.')}<div class="form-actions"><button class="button" data-action="begin-part" data-id="${id}">Mulai ${subtests[r.part].short}${icon('arrow')}</button>${textLink('Kembali ke detail',routeFor(p))}</div></section></div>`;
 const s=subtests[r.part],q=s.questions[r.q],a=r.answers[r.part+'-'+r.q],n=s.questions.filter((_,i)=>answered(r.answers[r.part+'-'+i])).length;
 if(mode==='kumpulkan')return `${examHeader(p,r)}<div class="exam-center"><section class="panel"><h1>Kumpulkan subtes ${s.short}?</h1><p>${n} dari ${s.questions.length} soal sudah dijawab. ${s.questions.length-n?`${s.questions.length-n} soal masih kosong.`:'Semua soal sudah terisi.'}</p>${message('Setelah dikumpulkan, jawaban subtes ini tidak dapat diubah. Timer tetap berjalan selama kamu meninjau halaman ini.')}<div class="form-actions"><button class="button" data-action="submit-part" data-id="${id}">Kumpulkan ${s.short}${icon('arrow')}</button>${action('Periksa kembali','/ujian/'+id,true)}</div></section></div>`;
 return `${examHeader(p,r)}<div class="exam-layout"><div><section class="question-card"><div class="question-kicker"><span>Soal ${r.q+1} dari ${s.questions.length}</span><span>${q.type==='multi'?'Pilih lebih dari satu jawaban':q.type==='text'?'Isian singkat':q.type==='boolean'?'Benar atau salah':'Pilihan ganda'}</span></div><h1 class="question-text">${q.prompt}</h1>${q.type==='text'?`<label class="form-field">Jawabanmu<input class="short-answer" id="short-answer" inputmode="numeric" value="${esc(a??'')}" placeholder="Tulis jawaban"></label>`:q.options.map((o,i)=>`<label class="answer-option"><input name="answer" type="${q.type==='multi'?'checkbox':'radio'}" value="${i}" ${q.type==='multi'?(a||[]).includes(i)?'checked':'':a===i?'checked':''}><span class="answer-letter">${'ABCDE'[i]}</span><span>${o}</span></label>`).join('')}<p class="save-state" role="status">${answered(a)?'Jawaban demo tersimpan di browser.':'Pilih jawaban untuk melanjutkan.'}</p></section><div class="question-actions"><button class="button secondary" data-question="${r.q-1}" ${r.q===0?'disabled':''}>Sebelumnya</button>${r.q<s.questions.length-1?`<button class="button" data-question="${r.q+1}">Berikutnya${icon('arrow')}</button>`:action('Selesaikan subtes','/ujian/'+id+'/kumpulkan')}</div></div><aside class="question-nav"><h2>Navigasi soal</h2><div class="number-grid">${s.questions.map((_,i)=>`<button data-question="${i}" class="${i===r.q?'current':''} ${answered(r.answers[r.part+'-'+i])?'answered':''}" aria-label="Soal ${i+1}">${i+1}</button>`).join('')}</div><p class="summary-sub">${n} dijawab · ${s.questions.length-n} kosong</p>${action('Kumpulkan subtes','/ujian/'+id+'/kumpulkan',true)}<div class="subtest-stage-list">${subtests.map((part,i)=>`<div class="${i===r.part?'stage-current':''}">${part.short}<span>${i<r.part?'Terkunci':i===r.part?'Berjalan':'Belum dimulai'}</span></div>`).join('')}</div>${textLink('Kembali ke detail',routeFor(p))}</aside></div>`;
}
function startKec(id){let r=model.kec[id];if(!r||r.phase==='completed'){if(!(model.credits[id]>0)){go(routeFor(pFor(id)));return;}r=model.kec[id]={id:'kec-'+Date.now(),kind:'kecermatan',product:id,col:0,q:0,phase:'kolom',deadline:Date.now()+20000,answers:Array.from({length:10},()=>[])};}save();go('/tes-kecermatan/'+id);}
function nextColumn(r,start=Date.now()){r.col++;r.q=0;r.phase='kolom';r.deadline=start+20000;r.pauseUntil=null;}
const clamp=n=>Math.round(Math.max(0,Math.min(100,n))*100)/100;
function finishKec(r){if(r.phase==='completed')return;r.phase='completed';r.columns=r.answers.map((answers,c)=>{let correct=0,wrong=0,blank=0;for(let q=0;q<50;q++){const a=answers[q];if(a===undefined||a===null)blank++;else if(a===missingFor(c,q))correct++;else wrong++;}return{correct,wrong,blank};});r.counts=r.columns.reduce((t,c)=>({correct:t.correct+c.correct,wrong:t.wrong+c.wrong,blank:t.blank+c.blank}),{correct:0,wrong:0,blank:0});const answeredCount=r.counts.correct+r.counts.wrong,first=r.columns.slice(0,5).reduce((n,c)=>n+c.correct,0),second=r.columns.slice(5).reduce((n,c)=>n+c.correct,0);r.speed=clamp((answeredCount/500-.05)*100);r.accuracy=answeredCount?clamp(r.counts.correct/answeredCount*100):0;r.endurance=first?clamp((second/first-.05)*100):0;r.score=clamp(.3*r.speed+.45*r.accuracy+.25*r.endurance);r.date=dateNow();model.credits[r.product]=Math.max(0,(model.credits[r.product]||0)-1);model.history.push(JSON.parse(JSON.stringify(r)));}
function settleKec(r,now=Date.now()){let changed=false;for(let i=0;i<22;i++){if(r.phase==='kolom'&&now>=r.deadline){changed=true;if(r.col===9){finishKec(r);break;}r.phase='pause';r.pauseUntil=r.deadline+5000;}else if(r.phase==='pause'&&now>=r.pauseUntil){changed=true;nextColumn(r,r.pauseUntil);}else break;}if(changed)save();return changed;}
function kecExam(id){const p=pFor(id),r=model.kec[id];if(!r)return prepare(p);if(r.phase==='completed')return resultPage('kecermatan',r.id);if(r.phase==='pause')return `${examHeader(p,r,true)}<div class="exam-center"><section class="panel" style="text-align:center"><span class="answer-status">Kolom ${r.col+1} selesai</span><h1>Ambil napas sebentar.</h1><p>Kolom ${r.col+2} akan dimulai otomatis. Kamu juga bisa melanjutkan sekarang.</p><div class="pause-count" data-pause-count>${seconds(r.pauseUntil)}</div><button class="button" data-action="continue-kec" data-id="${id}">Lanjut ke kolom ${r.col+2}${icon('arrow')}</button></section></div>`;
 const refs=references(id,r.col);return `${examHeader(p,r,true)}<div class="kec-runtime"><p class="kec-label">Referensi kolom ${r.col+1}. Cocokkan item dengan labelnya.</p><div class="reference-grid">${refs.map((v,i)=>`<div class="reference-box"><small>${'ABCDE'[i]}</small><strong>${v}</strong></div>`).join('')}</div>${r.q<50?`<h1 class="kec-prompt">Item mana yang hilang?</h1><div class="shown-grid">${displayLabels(r.col,r.q).map(i=>`<div class="shown-box">${refs[i]}</div>`).join('')}</div><p class="kec-label">Soal ${r.q+1} / 50</p><div class="kec-answer-grid">${refs.map((_,i)=>`<button data-kec-answer="${i}" aria-label="Jawab ${'ABCDE'[i]}">${'ABCDE'[i]}</button>`).join('')}</div><div class="kec-bottom"><button class="text-button" data-kec-answer="skip">Lewati soal</button><span>Keyboard A–E juga bisa digunakan.</span></div>`:`<section class="panel"><h1 class="kec-prompt">Semua soal di kolom ini terjawab.</h1><p>Tunggu timer kolom selesai untuk melanjutkan.</p></section>`}<div class="kec-progress">${Array.from({length:10},(_,i)=>`<span class="${i<=r.col?'done':''}"></span>`).join('')}</div><p class="kec-label">Kolom ${r.col+1} dari 10 · ${r.q} soal dilewati atau dijawab</p></div>`;}
function answerKec(a){const id=currentPath.split('/')[2],r=model.kec[id];if(!r||r.phase!=='kolom'||r.q>=50)return;if(settleKec(r)){render();return;}r.answers[r.col][r.q]=a==='skip'?null:Number(a);r.q++;save();render();}
function findResult(kind,id){return model.history.find(r=>r.id===id&&r.kind===kind)||Object.values(kind==='tryout'?model.normal:model.kec).find(r=>r.id===id&&r.phase==='completed');}
function resultPage(kind,id){const r=findResult(kind,id);if(!r)return empty('Hasil belum tersedia.','Selesaikan latihan terlebih dahulu.','/latihan','Kembali ke latihan');const p=pFor(r.product),k=kind==='kecermatan',counts=r.counts||{correct:r.score,wrong:100-r.score,blank:0};return `${crumb(k?'Hasil kecermatan':'Hasil tryout',routeFor(p))}${title('Satu latihan sudah selesai.',p.title+' · '+r.date,action('Lihat pembahasan',`/pembahasan/${kind}/${id}`))}<div class="result-summary"><section class="result-main"><small>${k?'Nilai akhir':'Skor total'}</small><strong>${r.score.toLocaleString('id-ID',{maximumFractionDigits:2})}</strong><span>/ 100 · hasil simulasi</span></section><div class="stack"><div class="result-stat-grid">${[[counts.correct,'Benar'],[counts.wrong,'Salah'],[counts.blank,'Kosong']].map(([n,l])=>`<div class="result-stat"><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><section class="panel"><h2>${k?'Ritme, ketelitian, dan ketahanan.':'Pelajari sebelum mencoba lagi.'}</h2><p>${k?'Lihat rekap tiap kolom untuk memahami akurasi dan ritme pengerjaanmu.':'Pembahasan membantu memahami jawaban dan bagian yang perlu diperbaiki. Setiap percobaan tersimpan terpisah.'}</p></section></div></div>${k?`<div class="result-stat-grid" style="margin-bottom:24px">${[[r.speed,'Kecepatan'],[r.accuracy,'Ketelitian'],[r.endurance,'Ketahanan']].map(([n,l])=>`<div class="result-stat"><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><div class="detail-grid"><section class="panel"><h2>Rekap per kolom</h2><div class="table-wrap"><table class="column-table"><thead><tr><th>Kolom</th><th>Benar</th><th>Salah</th><th>Kosong</th></tr></thead><tbody>${r.columns.map((c,i)=>`<tr><td>${i+1}</td><td>${c.correct}</td><td>${c.wrong}</td><td>${c.blank}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Jawaban benar per kolom</h2><div class="column-bars">${r.columns.map((c,i)=>`<div><small>${c.correct}</small><span style="height:${Math.max(2,c.correct/50*100)}%"></span><small>${i+1}</small></div>`).join('')}</div>${message(`Sisa kuota untuk tes ini: ${model.credits[p.id]||0} kesempatan. Satu kuota sudah digunakan setelah percobaan ini selesai.`)}</section></div>`:`<section class="panel"><h2>Skor per subtes</h2><div class="score-bars">${subtests.map((s,i)=>{const n=r.parts?.[i]??[80,86,86][i];return `<div><div class="bar-label"><span>${s.name}</span><strong>${n} / 100</strong></div><div class="bar-track"><span style="width:${n}%"></span></div></div>`;}).join('')}</div>${message(r.sample?'Hasil historis ini adalah data contoh. Pembahasan menampilkan cuplikan soal demo.':'Skor demo memakai enam soal contoh. Penilaian sebenarnya tetap mengikuti konfigurasi tryout di aplikasi.')}</section>`}<div class="form-actions">${action('Lihat riwayat & coba lagi',routeFor(p),true)}${action('Kembali ke dashboard','/dashboard',true)}</div>`;}
function review(kind,id,column=0,offset=0){const r=findResult(kind,id);if(!r)return resultPage(kind,id);const p=pFor(r.product);if(kind==='kecermatan'){const refs=references(p.id,column);return `${crumb('Hasil kecermatan',`/hasil/${kind}/${id}`)}${title('Pembahasan kecermatan',p.title+' · Kolom '+(column+1))}<div class="filters"><label class="form-field">Pilih kolom<select id="review-column" data-run="${id}">${Array.from({length:10},(_,i)=>`<option value="${i}" ${i===column?'selected':''}>Kolom ${i+1}</option>`).join('')}</select></label><span class="quiet-chip">Soal ${offset*10+1}–${Math.min(50,offset*10+10)} / 50</span></div><section class="panel">${Array.from({length:10},(_,i)=>i+offset*10).filter(q=>q<50).map(q=>{const answer=r.answers[column][q],missing=missingFor(column,q),correct=answer===missing;return `<article class="review-question"><span class="answer-status ${correct?'correct':''}">${answer==null?'Kosong':correct?'Benar':'Salah'}</span><h3>Soal ${q+1}. Item mana yang hilang?</h3><p>Referensi: ${refs.map((v,i)=>`${'ABCDE'[i]}: ${v}`).join(' / ')}</p><p>Ditampilkan: ${displayLabels(column,q).map(i=>refs[i]).join(' / ')}</p><p>Jawabanmu: <strong>${answer==null?'—':'ABCDE'[answer]}</strong> · Jawaban benar: <strong>${'ABCDE'[missing]} (${refs[missing]})</strong></p></article>`;}).join('')}</section><div class="form-actions">${offset>0?action('Sebelumnya',`/pembahasan/${kind}/${id}/${column}/${offset-1}`,true):''}${offset<4?action('10 soal berikutnya',`/pembahasan/${kind}/${id}/${column}/${offset+1}`):''}${action('Kembali ke hasil',`/hasil/${kind}/${id}`,true)}</div>`;}
 return `${crumb('Hasil tryout',`/hasil/${kind}/${id}`)}${title('Pahami setiap jawaban.',p.title)}<section class="panel">${subtests.map((s,si)=>s.questions.map((q,qi)=>{const a=r.sample?(si===0?q.key:null):r.answers[si+'-'+qi],ok=answered(a)&&scoreAnswer(q,a),show=value=>q.type==='multi'?(value||[]).map(i=>q.options[i]).join('; '):q.type==='text'?esc(value):value==null?'—':q.options[value];return `<article class="review-question"><span class="answer-status ${ok?'correct':''}">${s.short} · ${!answered(a)?'Kosong':ok?'Benar':'Salah'}</span><h3>${qi+1}. ${q.prompt}</h3><p>Jawabanmu: <strong>${answered(a)?show(a):'—'}</strong></p><p>Jawaban benar: <strong>${show(q.key)}</strong></p>${message(q.explanation)}</article>`;}).join('')).join('')}</section><div class="form-actions">${action('Kembali ke hasil',`/hasil/${kind}/${id}`,true)}</div>`;}
function addToCart(id){const p=pFor(id);if(p.kind==='tryout'&&has(p)){go(routeFor(p));return;}if(!model.cart.includes(id))model.cart.push(id);model.selectedCart=id;save();go('/keranjang');}
function cart(){if(!model.cart.length)return `${title('Keranjang','Simpan latihan yang ingin kamu beli.')}${empty('Keranjang masih kosong.','Jelajahi katalog, lalu tambahkan tryout atau kuota tes kecermatan.')}`;const p=selectedProduct();return `${crumb('Katalog','/katalog')}${title('Keranjang latihanmu.','Pilih produk yang ingin kamu bayar sekarang. Produk lain tetap tersimpan di keranjang.')}<div class="detail-grid"><section class="panel">${model.cart.map(id=>{const item=pFor(id);return `<div class="cart-row"><input class="cart-select" type="radio" name="cart-product" aria-label="Pilih ${item.title}" value="${id}" ${id===p.id?'checked':''}><span class="product-symbol ${item.tone}">${icon(item.icon)}</span><div class="cart-description"><h3>${item.title}</h3><p>${item.kind==='tryout'?'Akses tryout':item.credits+' kesempatan tes'} · ${item.program}</p><button class="text-button" data-remove="${id}">Hapus</button></div><strong class="cart-price">${rp(item.price)}</strong></div>`;}).join('')}${message('Satu produk per pembayaran. Kamu bisa kembali untuk membayar produk lainnya.')}${textLink('Tambahkan latihan lain','/katalog')}</section><aside class="panel sticky-summary"><h2>Ringkasan pembayaran</h2><p>${p.title}</p><div class="summary-line"><span>${p.kind==='tryout'?'Akses tryout':'Kuota '+p.credits+' kesempatan'}</span><strong>${rp(p.price)}</strong></div><div class="summary-line total"><span>Total</span><strong>${rp(p.price)}</strong></div>${action('Lanjut ke checkout','/checkout/'+p.id)}${message('Seluruh harga dan transaksi di prototype ini adalah contoh.')}</aside></div>`;}
function methods(total,topup=false){return `${(!topup?['saldo','online','manual']:['online','manual']).map(m=>`<label class="payment-method ${method===m?'active':''}"><input type="radio" name="payment-method" value="${m}" ${method===m?'checked':''}>${icon(m==='saldo'?'wallet':m==='online'?'grid':'receipt')}<span><strong>${m==='saldo'?'Saldo akun':m==='online'?'Pembayaran online':'Transfer manual'}</strong><small>${m==='saldo'?`Tersedia ${rp(model.balance)}${model.balance<total?' · saldo belum cukup':''}`:m==='online'?'Virtual account, QRIS, atau metode lain':'Unggah bukti, lalu tunggu verifikasi'}</small></span></label>`).join('')}`;}
function checkout(id,topup=false){const p=pFor(id),total=topup?amount:p.price;if(method==='saldo'&&topup)method='online';return `${crumb(topup?'Saldo':'Keranjang',topup?'/akun/transaksi':'/keranjang')}${title(topup?'Isi saldo akun.':'Selesaikan pembayaran.',topup?'Pilih nominal, lalu lanjut ke metode pembayaran.':p.title)}<div class="detail-grid"><section class="panel">${topup?`<h2>Nominal isi saldo</h2><div class="amount-options">${[25000,50000,100000].map(n=>`<button data-amount="${n}" class="${amount===n?'active':''}">${rp(n)}</button>`).join('')}</div><label class="form-field">Nominal lainnya<input id="topup-amount" type="number" min="10000" step="1000" value="${amount}" inputmode="numeric"></label>${message('Nominal minimum contoh: Rp10.000. Nilai sebenarnya mengikuti pengaturan bimbel.')}`:''}<h2 style="margin-top:${topup?'28':'0'}px">Metode pembayaran</h2>${methods(total,topup)}${method==='saldo'&&model.balance<total?message('Saldo belum cukup untuk pembelian ini. '+textLink('Isi saldo','/isi-saldo')):''}${message(method==='manual'?'Akses atau saldo bertambah setelah bukti transfer disetujui.':'Akses atau saldo bertambah setelah pembayaran dikonfirmasi.')}</section><aside class="panel sticky-summary"><h2>Ringkasan</h2><p>${topup?'Isi saldo akun':p.title}</p><div class="summary-line"><span>${topup?'Nominal isi saldo':'Harga produk'}</span><strong>${rp(total)}</strong></div><div class="summary-line total"><span>Total</span><strong>${rp(total)}</strong></div><button class="button wide-button" data-action="pay" data-id="${topup?'topup':id}" ${(total<10000||method==='saldo'&&model.balance<total)?'disabled':''}>${method==='saldo'?'Bayar dengan saldo':'Lanjut ke pembayaran'}${icon('arrow')}</button>${message('Mode prototype: tidak ada potongan uang atau pembayaran sungguhan.')}</aside></div>`;}
function grant(order){if(order.granted||order.status!=='confirmed')return;order.granted=true;if(order.kind==='topup')model.balance+=order.amount;else{const p=pFor(order.product);if(p.kind==='tryout'){if(!model.holdings.includes(p.id))model.holdings.push(p.id);}else model.credits[p.id]=(model.credits[p.id]||0)+p.credits;model.cart=model.cart.filter(id=>id!==p.id);if(model.selectedCart===p.id)model.selectedCart=model.cart[0]||null;}save();}
function pay(id){const topup=id==='topup',p=pFor(id),total=topup?amount:p.price;if(total<10000)return;if(method==='saldo'&&model.balance<total)return;const order={id:'DEMO-'+Date.now(),kind:topup?'topup':'product',product:topup?null:p.id,amount:total,method,status:method==='saldo'?'confirmed':'pending',date:dateNow(),granted:false};if(method==='saldo')model.balance-=total;model.orders.push(order);grant(order);save();go('/pembayaran/'+order.id);}
function payment(id){const o=model.orders.find(o=>o.id===id);if(!o)return empty('Pesanan tidak ditemukan.','Buka riwayat untuk memilih pesanan.','/akun/pesanan','Riwayat pesanan');const confirmed=o.status==='confirmed',failed=o.status==='failed',p=o.product?pFor(o.product):null;return `${crumb('Pesanan','/akun/pesanan')}<div class="status-banner ${confirmed?'success':failed?'failed':''}"><span class="status-icon">${icon(confirmed?'check':failed?'close':'clock')}</span><div><h1>${confirmed?'Pembayaran berhasil.':failed?'Pembayaran belum berhasil.':o.status==='review'?'Bukti transfer sedang diperiksa.':'Menunggu pembayaran.'}</h1><p>${confirmed?(o.kind==='topup'?'Saldo akunmu sudah bertambah.':'Akses latihanmu sudah tersedia.'):failed?'Akses belum diberikan dan saldo tidak berubah. Kamu bisa mencoba lagi.':o.status==='review'?'Akses akan dibuka setelah bukti disetujui.':'Ikuti instruksi pembayaran untuk melanjutkan.'}</p></div></div><div class="detail-grid"><section class="panel"><h2>${confirmed?'Ringkasan transaksi':failed?'Coba metode pembayaran lain':o.method==='online'?'Instruksi pembayaran online':'Instruksi transfer manual'}</h2>${!confirmed&&!failed?(o.method==='online'?`<p>Di aplikasi, metode pembayaran online akan dibuka melalui penyedia pembayaran.</p><div class="bank-number">VA / QRIS contoh</div>${message('Ini contoh instruksi. Tidak ada nomor rekening atau kode yang dapat dibayar.')}`:`<p>Transfer sesuai nominal pesanan, lalu unggah bukti untuk diperiksa.</p><div class="bank-number">XXXX–XXXX–1234</div><p>Bank contoh · Taruna Eduka · Tidak dapat digunakan untuk transfer.</p><form id="proof-form" data-order="${o.id}" style="margin-top:22px"><label class="form-field">Bukti transfer<input type="file" id="proof" accept="image/png,image/jpeg,application/pdf" required></label><button class="button" style="margin-top:14px">Kirim bukti contoh</button></form>`):`<p>${confirmed?'Transaksi contoh selesai. Kamu bisa melanjutkan persiapan.':'Transaksi ini belum memberikan akses latihan atau menambah saldo.'}</p>`}<div class="form-actions">${confirmed?(p?action(p.kind==='tryout'?'Buka tryout':'Buka tes kecermatan',routeFor(p)):'<button class="button" data-action="wallet">Lihat saldo akun'+icon('arrow')+'</button>'):failed?action('Coba bayar lagi',o.kind==='topup'?'/isi-saldo':'/checkout/'+o.product):''}${action('Riwayat pesanan','/akun/pesanan',true)}</div>${!confirmed&&!failed?`<div class="preview-controls"><span>Kontrol prototype pembayaran</span>${o.method==='manual'?`<button data-order-action="proof" data-order="${o.id}">Gunakan bukti contoh</button>`:''}<button data-order-action="success" data-order="${o.id}">${o.method==='manual'?'Simulasi disetujui':'Simulasi berhasil'}</button><button data-order-action="failed" data-order="${o.id}">Simulasi gagal</button></div>`:''}</section><aside class="panel"><p class="summary-title">${o.id}</p><h2>${p?p.title:'Isi saldo akun'}</h2><div class="summary-line"><span>Nominal</span><strong>${rp(o.amount)}</strong></div><div class="summary-line"><span>Metode</span><strong>${{saldo:'Saldo akun',online:'Online',manual:'Transfer manual'}[o.method]}</strong></div><div class="summary-line"><span>Status</span><strong>${confirmed?'Berhasil':failed?'Gagal':o.status==='review'?'Ditinjau':'Menunggu'}</strong></div>${message('Status di halaman ini adalah simulasi lokal. Tidak terhubung ke gateway atau rekening sungguhan.')}</aside></div>`;}
function wallet(){closeProfile();$('#account-content').innerHTML=`<h2>Saldo akun</h2><p>Untuk pembelian tryout dan kuota tes kecermatan.</p><div class="wallet-amount">${rp(model.balance)}</div><p>Saldo tersedia · data contoh</p><div class="wallet-quick-actions">${action('Isi saldo','/isi-saldo')}${action('Riwayat transaksi','/akun/transaksi',true)}</div><div class="transaction" style="margin-top:20px"><div>Aktivitas terakhir<small>Semua transaksi tercatat di riwayat.</small></div>${icon('wallet')}</div>`;$('#account-dialog').showModal();}
function accountPage(type){if(type==='profil')return `${crumb('Akun','/akun/profil')}${title('Profil akun.','Informasi yang membantu bimbel mengenalmu.')}<section class="panel" style="max-width:900px"><form id="profile-form"><div class="form-grid"><label class="form-field">Nama lengkap<input name="name" value="${esc(model.profile.name)}" required></label><label class="form-field">Email<input name="email" type="email" value="${esc(model.profile.email)}" required></label></div><div class="form-actions"><button class="button">Simpan perubahan contoh</button>${textLink('Bahasa & tampilan','/pengaturan')}</div>${message('Gunakan data contoh. Form ini hanya mengubah prototype di sesi browser, bukan akun aplikasi.')}</form></section>`;
 if(type==='pesanan')return `${crumb('Akun','/akun/profil')}${title('Riwayat pesanan.','Pantau pembelian tryout, kuota tes, dan isi saldo.')}<section class="panel">${model.orders.length?model.orders.slice().reverse().map(o=>`<a class="history-row" data-route="/pembayaran/${o.id}" href="#/pembayaran/${o.id}"><div>${o.product?pFor(o.product).title:'Isi saldo akun'}<small>${o.id} · ${o.date}</small></div><span class="quiet-chip">${{confirmed:'Berhasil',pending:'Menunggu',failed:'Gagal',review:'Ditinjau'}[o.status]}</span><strong>${rp(o.amount)}</strong></a>`).join(''):`<p>Belum ada pesanan di sesi prototype ini. ${textLink('Pilih latihan','/katalog')}</p>`}</section>`;
 return `${crumb('Saldo','/akun/profil')}${title('Riwayat transaksi.','Perubahan saldo dan pembelianmu dalam satu tempat.',action('Isi saldo','/isi-saldo'))}<div class="detail-grid"><section class="panel"><h2>Aktivitas saldo</h2>${model.orders.filter(o=>o.status==='confirmed'&&(o.kind==='topup'||o.method==='saldo')).slice().reverse().map(o=>`<div class="transaction"><div>${o.kind==='topup'?'Isi saldo':pFor(o.product).title}<small>${o.date} · ${o.id}</small></div><strong>${o.kind==='topup'?'+':'−'}${rp(o.amount)}</strong></div>`).join('')||'<p>Belum ada perubahan saldo di sesi prototype ini.</p>'}${message('Riwayat ini hanya contoh transaksi yang kamu simulasikan di prototype.')}</section><aside class="panel"><p class="summary-title">Saldo tersedia</p><div class="summary-price">${rp(model.balance)}</div>${action('Isi saldo','/isi-saldo')}</aside></div>`;}
function settings(preview=false){return `${crumb(preview?'Prototype':'Akun','/dashboard')}${title(preview?'Coba alur dan tampilannya.':'Tampilan ruang belajarmu.',preview?'Kontrol ini hanya untuk review prototype. Tidak mengubah aplikasi.':'Pilih tampilan yang nyaman digunakan.')}<section class="panel" style="max-width:900px"><div class="settings-row"><div><strong>Palet warna</strong><p>Bandingkan dusty rose dan biru Taruna.</p></div><select id="palette"><option value="rose" ${model.palette==='rose'?'selected':''}>Dusty rose / plum</option><option value="blue" ${model.palette==='blue'?'selected':''}>Biru Taruna</option></select></div><div class="settings-row"><div><strong>Tema</strong><p>Terang atau gelap, sesuai kenyamananmu.</p></div><select id="theme"><option value="light" ${model.theme==='light'?'selected':''}>Terang</option><option value="dark" ${model.theme==='dark'?'selected':''}>Gelap</option></select></div>${preview?`<div class="settings-row"><div><strong>Mulai ulang akun demo</strong><p>Menghapus jawaban dan transaksi contoh di sesi prototype ini.</p></div><div class="form-actions" style="margin:0"><button class="filter" data-reset="active">Akun aktif</button><button class="filter" data-reset="new">Akun baru</button></div></div><div class="settings-row"><div><strong>Kuota kecermatan habis</strong><p>Coba alur membeli tambahan kuota.</p></div><button class="filter" data-action="zero-credits">Simulasikan kuota 0</button></div>`:''}${message('Bahasa prototype lengkap ini adalah Indonesia. Halaman, jawaban, waktu, saldo, dan transaksi bersifat simulasi.')}<div class="form-actions">${action('Kembali ke dashboard','/dashboard',true)}${preview?'':action('Kontrol prototype','/preview',true)}</div></section>`;}
function verifyPage(){return `${crumb('Akun','/akun/profil')}<div class="preflight">${title('Verifikasi emailmu.','Masukkan kode enam digit dari email. Verifikasi tetap dapat dilewati.')}<section class="panel"><p>${esc(model.profile.email)}</p><form id="verify-form" style="margin-top:20px"><label class="form-field">Kode verifikasi<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required placeholder="000000"></label><div class="form-actions"><button class="button">Verifikasi contoh</button>${action('Lewati dulu','/dashboard',true)}</div></form>${message('Untuk melihat tampilan sukses, kode contoh prototype adalah 123456. Ini tidak berlaku di aplikasi sebenarnya.')}</section></div>`;}
function render(){setTheme();const path=(location.hash.slice(1)||'/dashboard').split('?')[0];const parts=path.split('/').filter(Boolean),[root,id,step]=parts;if(currentPath.split('/')[1]!==root){filter=location.hash.includes('jenis=kecermatan')?'kecermatan':'all';search='';}currentPath=path;const completed=root==='ujian'?model.normal[id]:root==='tes-kecermatan'?model.kec[id]:null;if(completed?.phase==='completed'){history.replaceState(null,'','#/hasil/'+completed.kind+'/'+completed.id);return render();}const exam=['ujian','tes-kecermatan'].includes(root);document.body.classList.toggle('exam-mode',exam);let html='';
 if(root==='dashboard')html=dashboard();else if(root==='latihan')html=library();else if(root==='katalog')html=library(true);else if(root==='keranjang')html=cart();else if(root==='tryout'||root==='kecermatan')html=step==='persiapan'?prepare(pFor(id)):detail(pFor(id));else if(root==='ujian')html=normalExam(id,step);else if(root==='tes-kecermatan')html=kecExam(id);else if(root==='hasil')html=resultPage(id,step);else if(root==='pembahasan')html=review(id,step,Number(parts[3]||0),Number(parts[4]||0));else if(root==='checkout')html=checkout(id);else if(root==='pembayaran')html=payment(id);else if(root==='isi-saldo')html=checkout(null,true);else if(root==='akun')html=id==='verifikasi'?verifyPage():accountPage(id);else if(root==='pengaturan'||root==='preview')html=settings(root==='preview');else if(root==='keluar')html=`<div class="signed-out"><h1>Sampai jumpa lagi.</h1><p class="empty-content">Ini halaman keluar prototype. Sesi akun aplikasi tidak berubah.</p>${action('Kembali ke demo','/dashboard')}</div>`;else html=dashboard();$('#main-content').innerHTML=html;
 $('#balance-top').textContent=rp(model.balance);$('.profile-name').innerHTML=`${esc(model.profile.name)}<small>Akun siswa</small>`;$('#profile-trigger .avatar').textContent=model.profile.name[0];$('#profile-trigger').setAttribute('aria-label','Buka menu akun '+model.profile.name.split(' ')[0]);$('.menu-identity .avatar').textContent=model.profile.name[0];$('.menu-identity strong').textContent=model.profile.name;$('.menu-identity small').textContent=model.profile.email;$('#profile-menu [data-account="wallet"] small').textContent='Saldo tersedia '+rp(model.balance);$('.prototype-label').innerHTML='Konsep alur <span>· Data contoh</span>';
 $$('.nav-item').forEach(a=>{const active=a.dataset.page==='dashboard'?root==='dashboard':a.dataset.page==='tryout'?['latihan','tryout','kecermatan','hasil','pembahasan'].includes(root):root==='katalog';a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});const badge=$('#cart-count');if(badge)badge.textContent=model.cart.length;$('#collapse').setAttribute('aria-label',document.body.classList.contains('expanded')?'Ciutkan sidebar':'Perluas sidebar');document.title=(exam?'Latihan':'Taruna Eduka')+' — Prototype alur siswa';}
const cartButton=document.createElement('a');cartButton.className='cart-shortcut';cartButton.href='#/keranjang';cartButton.dataset.route='/keranjang';cartButton.setAttribute('aria-label','Buka keranjang');cartButton.innerHTML=icon('receipt')+'<small id="cart-count">0</small>';$('.topbar-actions').prepend(cartButton);
$('#review-trigger').addEventListener('click',()=>go('/preview'));
$('#profile-trigger').addEventListener('click',()=>{const open=$('#profile-menu').hidden;$('#profile-menu').hidden=!open;$('#profile-trigger').setAttribute('aria-expanded',String(open));if(open)$('#profile-menu [data-account]').focus();});
$('#collapse').addEventListener('click',()=>{const expanded=document.body.classList.toggle('expanded');$('#collapse').setAttribute('aria-expanded',String(expanded));$('#collapse').setAttribute('aria-label',expanded?'Ciutkan sidebar':'Perluas sidebar');});
$('#account-dialog').addEventListener('close',()=>$('#profile-trigger').focus());
document.addEventListener('click',event=>{const target=event.target;
 const route=target.closest('[data-route]');if(route){event.preventDefault();if(route.dataset.route.startsWith('/checkout'))method='saldo';go(route.dataset.route);return;}
 const page=target.closest('[data-page]');if(page){event.preventDefault();go(({dashboard:'/dashboard',tryout:'/latihan',catalog:'/katalog',pengaturan:'/pengaturan'})[page.dataset.page]||'/dashboard');return;}
 const account=target.closest('[data-account]');if(account){const type=account.dataset.account;type==='wallet'?wallet():go(type==='profile'?'/akun/profil':'/akun/pesanan');return;}
 const add=target.closest('[data-add]');if(add){addToCart(add.dataset.add);return;}
 const remove=target.closest('[data-remove]');if(remove){model.cart=model.cart.filter(id=>id!==remove.dataset.remove);if(model.selectedCart===remove.dataset.remove)model.selectedCart=model.cart[0]||null;save();render();return;}
 const tab=target.closest('[data-hub]');if(tab){hub=tab.dataset.hub;filter='all';search='';render();return;}
 const f=target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return;}
 const q=target.closest('[data-question]');if(q){const r=model.normal[currentPath.split('/')[2]];r.q=Number(q.dataset.question);save();render();window.scrollTo(0,0);return;}
 const answer=target.closest('[data-kec-answer]');if(answer){answerKec(answer.dataset.kecAnswer);return;}
 const reset=target.closest('[data-reset]');if(reset){model=initial(reset.dataset.reset==='new');save();go('/dashboard');notify('Akun contoh dimulai ulang.');return;}
 const value=target.closest('[data-amount]');if(value){amount=Number(value.dataset.amount);render();return;}
 const orderAction=target.closest('[data-order-action]');if(orderAction){const o=model.orders.find(o=>o.id===orderAction.dataset.order);if(!o||o.status==='confirmed'||o.status==='failed')return;if(orderAction.dataset.orderAction==='proof'){o.status='review';o.proof=true;}else if(orderAction.dataset.orderAction==='success'){if(o.method==='manual'&&!o.proof){notify('Gunakan bukti contoh terlebih dahulu.');return;}o.status='confirmed';grant(o);}else o.status='failed';save();render();return;}
 const el=target.closest('[data-action]'),a=el?.dataset.action,id=el?.dataset.id;
 if(a==='theme'){model.theme=model.theme==='dark'?'light':'dark';save();setTheme();}
 if(a==='logout')go('/keluar');if(a==='wallet')wallet();if(a==='pay')pay(id);if(a==='begin-part')startNormal(id);if(a==='submit-part')submitPart(id);if(a==='continue-kec'){const r=model.kec[id];if(r?.phase==='pause'){nextColumn(r);save();render();}}
 if(a==='expire-normal'){const r=model.normal[id];if(r?.phase==='running'){r.deadline=Date.now()-1;tick();}}
 if(a==='expire-kec'){const r=model.kec[id];if(r?.phase==='kolom'){r.deadline=Date.now()-1;tick();}else if(r?.phase==='pause'){r.pauseUntil=Date.now()-1;tick();}}
 if(a==='zero-credits'){model.credits={};save();go('/kecermatan/campur');}
 if(target.closest('.dialog-close'))closeWallet();if(!target.closest('#profile-menu,#profile-trigger')&&!$('#profile-menu').hidden)closeProfile();
});
document.addEventListener('change',event=>{const e=event.target;if(e.name==='cart-product'){model.selectedCart=e.value;save();render();}if(e.name==='payment-method'){method=e.value;render();}if(e.id==='palette'){model.palette=e.value;save();setTheme();}if(e.id==='theme'){model.theme=e.value;save();setTheme();}if(e.id==='topup-amount'){amount=Math.max(0,Number(e.value));render();}if(e.id==='review-column')go(`/pembahasan/kecermatan/${e.dataset.run}/${e.value}/0`);
 if(e.name==='answer'){const r=model.normal[currentPath.split('/')[2]],q=subtests[r.part].questions[r.q];r.answers[r.part+'-'+r.q]=q.type==='multi'?$$('input[name="answer"]:checked').map(e=>Number(e.value)):Number(e.value);save();render();$('input[name="answer"][value="'+e.value+'"]').focus();}
});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='search'){const cursor=e.selectionStart;search=e.value;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);}if(e.id==='short-answer'){const r=model.normal[currentPath.split('/')[2]];r.answers[r.part+'-'+r.q]=e.value;save();$('.save-state').textContent='Jawaban demo tersimpan di browser.';}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='ready-form'){const id=form.dataset.id;pFor(id).kind==='tryout'?startNormal(id):startKec(id);}if(form.id==='profile-form'){const fd=new FormData(form);model.profile={name:String(fd.get('name')),email:String(fd.get('email'))};save();render();notify('Profil contoh disimpan di sesi prototype.');}if(form.id==='verify-form'){if(form.elements.code.value==='123456'){model.fresh=false;save();go('/dashboard');notify('Email contoh diverifikasi.');}else notify('Kode contoh belum cocok. Gunakan 123456.');}if(form.id==='proof-form'){const o=model.orders.find(o=>o.id===form.dataset.order);if(o){o.proof=true;o.status='review';save();render();}}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#profile-menu').hidden){closeProfile();$('#profile-trigger').focus();}if(!event.ctrlKey&&!event.metaKey&&!event.altKey&&currentPath.startsWith('/tes-kecermatan/')&&!/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)&&/^[a-e]$/i.test(event.key)){event.preventDefault();answerKec('ABCDE'.indexOf(event.key.toUpperCase()));}});
function tick(){const now=Date.now();Object.values(model.normal).forEach(r=>{if(r.phase==='running'&&now>=r.deadline)submitPart(r.product,true);});Object.values(model.kec).forEach(r=>{if(settleKec(r,now)&&currentPath==='/tes-kecermatan/'+r.product){if(r.phase==='completed')go('/hasil/kecermatan/'+r.id,false);else render();}});const root=currentPath.split('/')[1],id=currentPath.split('/')[2],r=root==='ujian'?model.normal[id]:root==='tes-kecermatan'?model.kec[id]:null;if(r){$$('[data-clock]').forEach(el=>el.textContent=time(seconds(r.phase==='pause'?r.pauseUntil:r.deadline||now)));$$('[data-pause-count]').forEach(el=>el.textContent=seconds(r.pauseUntil));}}
$('#account-dialog').addEventListener('click',e=>{if(e.target===$('#account-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeWallet();}});
window.addEventListener('hashchange',()=>{closeWallet();closeProfile();render();window.scrollTo(0,0);});
if(!location.hash)history.replaceState(null,'','#/dashboard');if(location.hash.includes('jenis=kecermatan'))filter='kecermatan';render();tick();setInterval(tick,250);
